SELECT 
FROM sekai_Draw_lots_task
WHERE id = #{id}
  AND user_id = #{userId}
LIMIT 1

SELECT FROM sekai_Draw_lots_task WHERE user_id = #{userId}
AND status = 'OPEN'
AND status = 'DONE'
AND status = 'ARCHIVED'
AND status <> 'ARCHIVED'
ORDER BY CASE status WHEN 'OPEN' THEN 0 WHEN 'DONE' THEN 1 ELSE 2 END, CASE WHEN due_date IS NULL THEN 1 ELSE 0 END, due_date ASC, priority DESC, id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM sekai_Draw_lots_task
WHERE user_id = #{userId}
  AND title = #{title}
  AND status <> 'ARCHIVED'

mapper.update:
UPDATE sekai_Draw_lots_task
SET status = #{status},
    completed_time = #{completedTime}
WHERE id = #{id}
  AND user_id = #{userId}
